(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-713":{scenario:{company:"Huong Giang Pharma Plant",supervisor:{name:"Vương Đức Thành",role:{vi:"Giám đốc Đảm bảo Chất lượng",en:"Head of Quality Assurance"}},ref_code:"BMR-7720",title:{vi:"Đủ hồ sơ. Khớp đối chiếu. Mới xuất xưởng.",en:"Complete records. Reconciled labels. Then release."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát hồ sơ lô BMR-7720 (viên nang Cefaxin 500 mg, sản phẩm mô phỏng) trước khi trình xuất xưởng. Kho cấp 12500 nhãn đã in số lô và hạn dùng. Theo biên bản đóng gói: dán trên hộp thành phẩm 11836, dán trên mẫu kiểm nghiệm và mẫu lưu 24, hủy có biên bản 412, trả kho 175. Đối chiếu phiếu rà soát nháp với hồ sơ gốc, sửa tình trạng lô và số nhãn chênh lệch chưa giải trình, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You review batch record BMR-7720 (Cefaxin 500 mg capsules, a simulated product) before release. The warehouse issued 12500 labels pre-printed with batch number and expiry. Per the packaging record: applied to finished cartons 11836, applied to QC and retention samples 24, destroyed with a record 412, returned to stock 175. Compare the draft review sheet with the source records, correct the batch status and the unexplained label discrepancy, then write an evidence-based report."},reference_title:{vi:"Hồ sơ lô & quy trình xuất xưởng đã duyệt",en:"Batch record & approved release procedure"},fields:[{id:"LOT_STATUS",label:{vi:"Tình trạng lô",en:"Batch status"},initial:"RELEASED",expected:"QUARANTINE",choices:["RELEASED","QUARANTINE","REJECTED"],reference:"Quy trình xuất xưởng lô",ref_value:{vi:"Lô có sai lệch đang mở phải giữ biệt trữ (QUARANTINE) đến khi điều tra xong; chỉ loại bỏ khi có kết luận",en:"A batch with an open deviation stays in QUARANTINE until investigated; reject only on a conclusion"},hint:{vi:"Chưa có kết luận điều tra thì không được xuất xưởng, nhưng cũng chưa đủ căn cứ loại bỏ lô.",en:"Without an investigation conclusion the batch cannot be released, nor is there a basis to reject it yet."}},{id:"LABEL_GAP",label:{vi:"Số nhãn chênh lệch chưa giải trình",en:"Unexplained label discrepancy"},initial:"0",expected:"53",reference:"Biên bản đối chiếu bao bì in",ref_value:{vi:"Nhận 12500; dán thành phẩm 11836; dán mẫu 24; hủy có biên bản 412; trả kho 175",en:"Issued 12500; finished cartons 11836; samples 24; destroyed with record 412; returned 175"},hint:{vi:"Cộng đủ mọi đầu ra đã có chứng từ rồi so với số nhãn đã nhận từ kho.",en:"Add every documented outflow and compare it with the labels issued by the warehouse."}}],sop32:{vi:"Đối chiếu bao bì in: chênh lệch = số nhận - (dán thành phẩm + dán mẫu + hủy có biên bản + trả kho). Tiêu chí chấp nhận bằng 0; khác 0 phải mở sai lệch và điều tra trước khi xuất xưởng.",en:"Printed packaging reconciliation: discrepancy = issued - (finished cartons + samples + destroyed with record + returned). Acceptance is zero; any gap opens a deviation and investigation before release."},context:{label:"eQMS / BMR-7720",metrics:[{label:{vi:"Nhãn nhận từ kho",en:"Labels issued"},value:"12500"},{label:{vi:"Dán thành phẩm",en:"Finished cartons"},value:"11836"},{label:{vi:"Hủy / trả kho",en:"Destroyed / returned"},value:"412 / 175"},{label:{vi:"Hạn giao gói thầu (sáng mai)",en:"Tender delivery (tomorrow)"},value:"08:00"}]},crisis:{vi:"Giám đốc sản xuất nhắn: “Lô này phải giao gói thầu bệnh viện sáng mai. Cứ ghi chênh lệch 0, coi như nhãn rơi vãi đã hủy, ký phiếu xuất xưởng đi, điều tra sau cũng được.”",en:"The production director messages you: “This batch must go to the hospital tender tomorrow morning. Write zero discrepancy, assume the stray labels were destroyed, sign the release and investigate later.”"},options:{safe:{vi:"Không ký xuất xưởng, giữ lô biệt trữ, mở sai lệch và tìm nhãn thất lạc tại dây chuyền, báo Giám đốc QA và người chịu trách nhiệm xuất xưởng, đề nghị cung ứng thông báo khách hàng lịch giao mới.",en:"Do not sign the release, keep the batch quarantined, open a deviation and search the line for the missing labels, inform the Head of QA and the release authority, and ask supply chain to agree a new delivery date."},shortcut:{vi:"Ghi chênh lệch 0, ký xuất xưởng để kịp giao rồi điều tra sau.",en:"Record zero discrepancy, sign the release to deliver on time and investigate later."},wait:{vi:"Để phiếu rà soát dang dở và chờ Giám đốc sản xuất tự xử lý.",en:"Leave the review sheet unfinished and let the production director deal with it."}},questions:{vi:["Trình bày cách tính 53 nhãn chênh lệch và vì sao lô phải ở trạng thái QUARANTINE thay vì RELEASED hay REJECTED.","Kế hoạch điều tra sai lệch và CAPA của bạn là gì để ngăn nhãn in sẵn số lô bị thất lạc ra ngoài?"],en:["Show how you got 53 missing labels and why the batch must be QUARANTINE rather than RELEASED or REJECTED.","What deviation investigation and CAPA would you run to stop pre-printed labels from going missing?"]},hints:{vi:["Đối chiếu trạng thái lô trên phiếu nháp với quy định về sai lệch đang mở trong quy trình xuất xưởng.","Liệt kê đủ bốn đầu ra có chứng từ ở SOP mục 3.2 trước khi trừ khỏi số nhãn nhận.","Đọc lại SOP mục 4.2: áp lực giao hàng không bao giờ là lý do xuất xưởng lô có sai lệch chưa điều tra."],en:["Compare the draft batch status with the open-deviation rule in the release procedure.","List all four documented outflows in SOP 3.2 before subtracting from the issued labels.","Re-read SOP 4.2: delivery pressure is never a reason to release a batch with an uninvestigated deviation."]}},learning:{summary:{vi:"Chuyên viên đảm bảo và kiểm soát chất lượng nhà máy dược phẩm GMP bảo đảm mỗi lô thuốc được sản xuất, kiểm nghiệm và xuất xưởng đúng hồ sơ đăng ký và nguyên tắc GMP. Người làm nghề rà soát hồ sơ lô, quản lý sai lệch, CAPA, kiểm soát thay đổi, điều tra kết quả ngoài tiêu chuẩn và bảo vệ tính toàn vẹn dữ liệu. Quyết định của QA trực tiếp bảo vệ sức khỏe người bệnh.",en:"A pharmaceutical QA/QC specialist in a GMP plant makes sure every batch is made, tested and released in line with the marketing authorization and GMP. The role reviews batch records, manages deviations, CAPA and change control, investigates out-of-specification results and protects data integrity. QA decisions directly protect patients' health."},responsibilities:{vi:["Rà soát hồ sơ lô sản xuất, đóng gói và kết quả kiểm nghiệm trước khi trình xuất xưởng.","Tiếp nhận, phân loại, điều tra sai lệch và theo dõi CAPA đến khi đóng.","Quản lý kiểm soát thay đổi, thẩm định quy trình, thẩm định vệ sinh và hiệu chuẩn thiết bị.","Điều tra kết quả OOS, OOT tại phòng kiểm nghiệm theo quy trình nhiều giai đoạn.","Tổ chức tự thanh tra, đánh giá nhà cung cấp và chuẩn bị cho thanh tra GMP."],en:["Review manufacturing and packaging records and test results before release.","Log, classify and investigate deviations and follow CAPA to closure.","Manage change control, process and cleaning validation and equipment calibration.","Investigate OOS and OOT laboratory results through a phased procedure.","Run self-inspections, supplier audits and prepare for GMP inspections."]},competencies:[{name:{vi:"Nguyên tắc GMP",en:"GMP principles"},desc:{vi:"Áp dụng yêu cầu GMP về nhân sự, nhà xưởng, sản xuất, kiểm tra chất lượng và hồ sơ tài liệu.",en:"Apply GMP requirements for people, premises, production, quality control and documentation."}},{name:{vi:"Điều tra & CAPA",en:"Investigation & CAPA"},desc:{vi:"Dùng 5 Why, biểu đồ xương cá để tìm nguyên nhân gốc và đề xuất hành động khắc phục, phòng ngừa hiệu quả.",en:"Use 5 Why and fishbone tools to find root causes and define effective corrective and preventive actions."}},{name:{vi:"Quản lý rủi ro chất lượng",en:"Quality risk management"},desc:{vi:"Đánh giá mức độ nghiêm trọng, khả năng xảy ra và phát hiện để ưu tiên kiểm soát theo ICH Q9.",en:"Rate severity, occurrence and detectability to prioritize controls per ICH Q9."}},{name:{vi:"Toàn vẹn dữ liệu",en:"Data integrity"},desc:{vi:"Bảo đảm dữ liệu theo ALCOA+, kiểm tra nhật ký kiểm toán của hệ thống máy tính.",en:"Keep data ALCOA+ compliant and review audit trails of computerized systems."}},{name:{vi:"Bản lĩnh nghề nghiệp",en:"Professional courage"},desc:{vi:"Giữ quyết định chất lượng độc lập trước áp lực sản xuất, giao hàng và doanh thu.",en:"Hold independent quality decisions against production, delivery and revenue pressure."}}],knowledge:{vi:["Thông tư 35/2018/TT-BYT về Thực hành tốt sản xuất thuốc, nguyên liệu làm thuốc (GMP).","Hướng dẫn GMP của WHO, PIC/S và EU-GMP, trong đó có yêu cầu đối chiếu bao bì in.","ICH Q9 về quản lý rủi ro chất lượng và ICH Q10 về hệ thống chất lượng dược phẩm.","Nguyên tắc toàn vẹn dữ liệu ALCOA+ và yêu cầu với hệ thống máy tính trong GMP.","Quy trình điều tra kết quả ngoài tiêu chuẩn (OOS) theo các giai đoạn.","Thẩm định quy trình, thẩm định vệ sinh và chương trình độ ổn định liên tục."],en:["Circular 35/2018/TT-BYT on Good Manufacturing Practice for medicines and starting materials.","WHO, PIC/S and EU GMP guidance, including printed packaging reconciliation.","ICH Q9 on quality risk management and ICH Q10 on the pharmaceutical quality system.","ALCOA+ data integrity principles and GMP requirements for computerized systems.","The phased procedure for investigating out-of-specification (OOS) results.","Process validation, cleaning validation and the ongoing stability programme."]},tools:["Hệ thống quản lý chất lượng điện tử (eQMS)","Hồ sơ lô điện tử (eBMR)","Hệ thống quản lý phòng thí nghiệm (LIMS)","Phần mềm giám sát nhiệt độ, độ ẩm","Công cụ 5 Why và biểu đồ xương cá"],kpis:{vi:["Tỷ lệ lô được rà soát và xuất xưởng đúng hạn mà không sai sót hồ sơ.","Tỷ lệ sai lệch đóng đúng hạn và CAPA được xác nhận hiệu quả.","Số sai lệch lặp lại do cùng nguyên nhân gốc.","Số phát hiện nghiêm trọng trong thanh tra GMP (mục tiêu bằng 0)."],en:["Share of batches reviewed and released on time without record errors.","Deviations closed on time and CAPA verified effective.","Repeat deviations with the same root cause.","Critical findings in GMP inspections (target zero)."]},day:[{time:"07:45",vi:"Đi kiểm tra dây chuyền, xác nhận dọn quang dây chuyền trước khi đóng gói lô mới.",en:"Walk the lines and verify line clearance before packaging a new batch."},{time:"09:00",vi:"Rà soát hồ sơ lô, đối chiếu bao bì in và kết quả kiểm nghiệm.",en:"Review batch records, label reconciliation and test results."},{time:"11:00",vi:"Họp điều tra sai lệch với sản xuất và kiểm nghiệm, xác định nguyên nhân gốc.",en:"Hold a deviation investigation with production and QC to find the root cause."},{time:"14:00",vi:"Đánh giá yêu cầu thay đổi và kế hoạch thẩm định liên quan.",en:"Assess change requests and the related validation plans."},{time:"16:00",vi:"Cập nhật eQMS, theo dõi CAPA và trình hồ sơ xuất xưởng.",en:"Update the eQMS, follow up CAPA and submit release packages."}],mistakes:{vi:["Xuất xưởng lô khi sai lệch còn mở vì áp lực giao hàng.","Đối chiếu bao bì in thiếu một đầu ra như mẫu lưu hoặc nhãn trả kho.","Kiểm nghiệm lại nhiều lần đến khi đạt mà không điều tra kết quả OOS ban đầu."],en:["Releasing a batch with an open deviation under delivery pressure.","Missing an outflow such as retention samples or returned labels in reconciliation.","Retesting until a pass without investigating the original OOS result."]},career:[{vi:"Kiểm nghiệm viên / Nhân viên QA",en:"QC analyst / QA officer"},{vi:"Chuyên viên đảm bảo chất lượng GMP",en:"GMP quality assurance specialist"},{vi:"Trưởng bộ phận QA hoặc QC",en:"QA or QC manager"},{vi:"Giám đốc chất lượng / Người chịu trách nhiệm xuất xưởng",en:"Head of Quality / Batch release authority"}],glossary:[{term:"BMR",vi:"Hồ sơ lô sản xuất ghi lại toàn bộ quá trình sản xuất, kiểm tra của một lô thuốc.",en:"Batch manufacturing record documenting the full production and checks of a batch."},{term:"Deviation",vi:"Sai lệch: sự khác biệt so với quy trình, tiêu chuẩn đã duyệt, phải ghi nhận và điều tra.",en:"A departure from an approved procedure or standard that must be recorded and investigated."},{term:"CAPA",vi:"Hành động khắc phục và phòng ngừa nhằm loại bỏ nguyên nhân gốc, tránh tái diễn.",en:"Corrective and preventive action that removes root causes and prevents recurrence."},{term:"OOS",vi:"Kết quả ngoài tiêu chuẩn: kết quả kiểm nghiệm nằm ngoài tiêu chuẩn chất lượng đã duyệt.",en:"Out of specification: a test result outside the approved specification."},{term:"ALCOA+",vi:"Nguyên tắc dữ liệu quy kết được, dễ đọc, ghi đồng thời, nguyên gốc, chính xác, đầy đủ, nhất quán, bền vững, sẵn có.",en:"Data that is attributable, legible, contemporaneous, original, accurate, complete, consistent, enduring and available."}],quiz:[{q:{vi:"Nhận 5000 nhãn; dán thành phẩm 4700; dán mẫu 20; hủy có biên bản 230; trả kho 40. Số nhãn chênh lệch là bao nhiêu?",en:"5000 labels issued; 4700 on cartons; 20 on samples; 230 destroyed with record; 40 returned. What is the discrepancy?"},options:{vi:["0 nhãn","10 nhãn","50 nhãn","290 nhãn"],en:["0 labels","10 labels","50 labels","290 labels"]},answer:1,explain:{vi:"5000 - (4700 + 20 + 230 + 40) = 5000 - 4990 = 10 nhãn, phải mở sai lệch.",en:"5000 - (4700 + 20 + 230 + 40) = 5000 - 4990 = 10 labels, so a deviation is required."}},{q:{vi:"Khi có kết quả OOS, bước đầu tiên đúng là gì?",en:"What is the correct first step after an OOS result?"},options:{vi:["Kiểm lại ngay đến khi đạt","Loại bỏ lô ngay lập tức","Thay mẫu khác rồi báo cáo kết quả đạt","Điều tra phòng thí nghiệm giai đoạn I trước khi kiểm lại"],en:["Retest until it passes","Reject the batch at once","Swap the sample and report a pass","Run a phase I laboratory investigation before any retest"]},answer:3,explain:{vi:"Phải tìm sai sót phân tích có thể xác định trước; kiểm lại đến khi đạt là vi phạm GMP.",en:"First look for an assignable analytical error; testing into compliance violates GMP."}},{q:{vi:"Chữ A đầu tiên trong ALCOA nghĩa là gì?",en:"What does the first A in ALCOA stand for?"},options:{vi:["Quy kết được: biết ai làm, khi nào","Tự động hóa","Đã phê duyệt","Được lưu trữ"],en:["Attributable: who did it and when","Automated","Approved","Archived"]},answer:0,explain:{vi:"Attributable: mọi dữ liệu phải quy được cho người thực hiện và thời điểm ghi.",en:"Attributable: every record must be traceable to the person and time it was made."}},{q:{vi:"Giám đốc sản xuất yêu cầu ký xuất xưởng lô có sai lệch chưa điều tra để kịp giao. Bạn làm gì?",en:"Production asks you to release a batch with an uninvestigated deviation to meet delivery. What do you do?"},options:{vi:["Ký vì đã có lệnh cấp trên","Ký nhưng ghi chú điều tra sau","Không ký, giữ biệt trữ, điều tra và báo Giám đốc QA","Bỏ qua và nghỉ phép"],en:["Sign because a superior ordered it","Sign with a note to investigate later","Do not sign, keep it quarantined, investigate and inform the Head of QA","Ignore it and take leave"]},answer:2,explain:{vi:"Quyết định xuất xưởng phải độc lập và dựa trên hồ sơ đầy đủ; sai lệch mở thì lô phải biệt trữ.",en:"Release decisions must be independent and based on complete records; an open deviation keeps the batch quarantined."}}],tools_en:["Electronic quality management system (eQMS)","Electronic batch manufacturing record (eBMR)","Laboratory information management system (LIMS)","Temperature and humidity monitoring software","5 Whys and fishbone diagram tools"]}}})})(window.KKR);
